  1 │ /**
  2 │  * BG-3 trust and abuse model: event triggers (file change, webhook).
  3 │  *
  4 │  * This file holds the trigger *spec format* (`nexus-trigger` v1) and its validation. A spec is the exact bytes an
  5 │  * operator approves by SHA-256; changed bytes are a different spec and need a new approval. Nothing here grants
  6 │  * anything: there is no "allow this trigger", "auto-fire this trigger" or "widen this policy" key. Every field either
  7 │  * narrows what may run or records how tightly it is bounded.
  8 │  *
  9 │  * BG-3 itself (the trigger firer that watches files and HTTP) is deferred to v1.4. This module is the trust and abuse
 10 │  * model that unblocks it: a firer built later imports `parseTriggerSpec`, `TriggerSpec`, `validateTriggerSpec`,
 11 │  * `defaultTriggerBounds` and the rate-limit constants from here and can trust that a spec it reads has already been
 12 │  * shaped and bounded by this code.
 13 │  *
 14 │  * Abuse surface covered:
 15 │  *   - only trusted workspaces may register triggers (workspace trust + content-hash approval, see trigger_trust.ts)
 16 │  *   - rate caps per trigger and per workspace (trigger_rate_limit.ts)
 17 │  *   - execution bounds below (max tool invocations, max rounds, max turn minutes)
 18 │  *   - no chain triggers: a trigger run may not register new triggers (enforced by the firer, not expressible here)
 19 │  *   - webhook secrets are never echoed and are validated constant-time (see trigger_trust.ts)
 20 │  *   - GG-3: triggers run unattended (no auto mode, no full access, no allow-always); they cannot approve a denied
 21 │  *     action, raise a verdict, widen a policy tier or remove a verification-file protection
 22 │  */
 23 │ 
 24 │ import * as fs from "node:fs";
 25 │ import * as path from "node:path";
 26 │ import { createHash } from "node:crypto";
 27 │ import { parseStrictJson, type StrictJsonOptions } from "./strict_json.js";
 28 │ 
 29 │ /** Every event kind a trigger can watch. No others are expressible; a spec naming another is rejected. */
 30 │ export const TRIGGER_EVENT_KINDS = ["file-change", "webhook"] as const;
 31 │ export type TriggerEventKind = (typeof TRIGGER_EVENT_KINDS)[number];
 32 │ 
 33 │ /** The policy under which a trigger's action runs. `worktree-write` only with the explicit `--allow-worktree-write`. */
 34 │ export const TRIGGER_POLICIES = ["read-only", "worktree-write"] as const;
 35 │ export type TriggerPolicy = (typeof TRIGGER_POLICIES)[number];
 36 │ 
 37 │ /** Format version. Every added/removed/changed key bumps it; readers refuse unknown versions. */
 38 │ export const TRIGGER_SPEC_FORMAT_VERSION = 1;
 39 │ 
 40 │ /** Hard bounds shared with trigger_rate_limit.ts. */
 41 │ export const TRIGGER_MAX_PATHS = 64;
 42 │ export const TRIGGER_MAX_PATH_GLOB = 256;
 43 │ export const TRIGGER_MAX_PROMPT = 4096;
 44 │ export const TRIGGER_MAX_SECRET = REDACTED;
 45 │ export const TRIGGER_MAX_ORIGINS = 16;
 46 │ export const TRIGGER_MAX_ORIGIN = 256;
 47 │ export const TRIGGER_MAX_ID = 64;
 48 │ export const TRIGGER_MAX_RULES = 32;
 49 │ export const TRIGGER_MAX_RULE = 256;
 50 │ 
 51 │ export const TRIGGER_DEFAULT_MAX_PER_MINUTE = 5;
 52 │ export const TRIGGER_DEFAULT_MAX_PER_HOUR = 60;
 53 │ export const TRIGGER_DEFAULT_MAX_PER_DAY = 500;
 54 │ export const TRIGGER_DEFAULT_MAX_TOOL_INVOCATIONS = 200;
 55 │ export const TRIGGER_DEFAULT_MAX_ROUNDS = 5;
 56 │ export const TRIGGER_DEFAULT_MAX_TURN_MINUTES = 30;
 57 │ 
 58 │ /** A validated trigger spec: what an event is, what runs when it fires, and how tightly it is bounded. */
 59 │ export interface TriggerSpec {
 60 │   format: "nexus-trigger";
 61 │   version: 1;
 62 │   /** `[a-z0-9][a-z0-9-]{0,62}`, unique in its workspace. Shown in receipts and denials. */
 63 │   id: string;
 64 │   /** What fires the trigger. */
 65 │   event: TriggerEvent;
 66 │   /** What runs when it fires. */
 67 │   action: TriggerAction;
 68 │   /** Rate caps (per trigger and per workspace). */
 69 │   rate: TriggerRate;
 70 │   /** Execution bounds. */
 71 │   bounds: TriggerBounds;
 72 │ }
 73 │ 
 74 │ export interface TriggerEvent {
 75 │   kind: TriggerEventKind;
 76 │   /** file-change: glob patterns relative to the workspace (no `..`, no absolute). At least one. */
 77 │   paths?: string[];
 78 │   /** webhook: shared secret, base64url, used to validate the caller (constant-time compare). */
 79 │   secret?: string;
 80 │   /** webhook: only these Origin/Host values may call (constant-time prefix match). Empty = any origin. */
 81 │   allowedOrigins?: string[];
 82 │ }
 83 │ 
 84 │ export interface TriggerAction {
 85 │   /** The objective / prompt the trigger runs. */
 86 │   prompt: string;
 87 │   /** `read-only` (default) or `worktree-write` (needs the explicit flag at approval). */
 88 │   policy: TriggerPolicy;
 89 │   /** Optional verifier command the run must pass (a discovered verifier still needs operator approval). */
 90 │   verifier?: string | null;
 91 │ }
 92 │ 
 93 │ export interface TriggerRate {
 94 │   /** Max firings of this trigger per rolling minute. */
 95 │   maxPerMinute: number;
 96 │   /** Max firings of this trigger per rolling hour. */
 97 │   maxPerHour: number;
 98 │   /** Max firings of this trigger per rolling day. */
 99 │   maxPerDay: number;
100 │ }
101 │ 
102 │ /** How far one firing of a trigger may go. Mirrored by the unattended budget defaults where sensible. */
103 │ export interface TriggerBounds {
104 │   /** Max tool invocations in one trigger run. */
105 │   maxToolInvocations: number;
106 │   /** Max sub-operation rounds. */
107 │   maxRounds: number;
108 │   /** Max minutes of one invocation. */
109 │   maxTurnMinutes: number;
110 │ }
111 │ 
112 │ /** The document stored in the trigger trust store (see trigger_trust.ts). */
113 │ export interface TriggerTrustStore {
114 │   version: 1;
115 │   entries: TriggerTrustEntry[];
116 │ }
117 │ 
118 │ export interface TriggerTrustEntry {
119 │   kind: "trigger";
120 │   /** The workspace's real path. */
121 │   scope: string;
122 │   /** The trigger id inside the scope. */
123 │   key: string;
124 │   /** SHA-256 of the approved spec bytes. */
125 │   sha256: string;
126 │   /** ISO 8601 time of the approval. */
127 │   approvedAt: string;
128 │   /** One line shown when approvals are listed. */
129 │   summary: string;
130 │ }
131 │ 
132 │ export type TriggerTrustStatus = "NEW" | "MATCH" | "MISMATCH" | "REMOVED" | "ABSENT";
133 │ 
134 │ export interface TriggerValidationProblem {
135 │   message: string;
136 │   pointer?: string;
137 │ }
138 │ 
139 │ const ID_RE = /^[a-z0-9][a-z0-9-]{0,62}$/;
140 │ const GLOB_RE = /^[^\0]*$/;
141 │ const PATH_SEGMENT_BAD = /(\.\.|^\/|\/\.\.)/;
142 │ const SECRET_RE = /^[A-Za-z0-9_-]+$/;
143 │ const ORIGIN_RE = /^(https?:\/\/)?[^\s/]+$/;
144 │ 
145 │ const isRecord = (value: unknown): value is Record<string, unknown> =>
146 │   Boolean(value) && typeof value === "object" && !Array.isArray(value);
147 │ 
148 │ const isString = (value: unknown): value is string => typeof value === "string";
149 │ 
150 │ function fail(message: string, pointer?: string): never {
151 │   throw new Error(`invalid trigger spec${pointer ? ` at ${pointer}` : ""}: ${message}`);
152 │ }
153 │ 
154 │ /** SHA-256 of the exact bytes of a spec (what is approved). */
155 │ export function triggerSpecSha256(bytes: Uint8Array): string {
156 │   return createHash("sha256").update(bytes).digest("hex");
157 │ }
158 │ 
159 │ /** The canonical, stable serialization of a spec for hashing: sorted keys, no whitespace. */
160 │ export function canonicalizeTriggerSpec(spec: TriggerSpec): string {
161 │   const ordered: Record<string, unknown> = {
162 │     format: spec.format,
163 │     version: spec.version,
164 │     id: spec.id,
165 │     event: {
166 │       kind: spec.event.kind,
167 │       ...(spec.event.paths !== undefined ? { paths: [...spec.event.paths].sort() } : {}),
168 │       ...(spec.event.secret !== undefined ? { secret: spec.event.secret } : {}),
169 │       ...(spec.event.allowedOrigins !== undefined
170 │         ? { allowedOrigins: [...spec.event.allowedOrigins].sort() }
171 │         : {}),
172 │     },
173 │     action: {
174 │       prompt: spec.action.prompt,
175 │       policy: spec.action.policy,
176 │       ...(spec.action.verifier !== undefined ? { verifier: spec.action.verifier } : {}),
177 │     },
178 │     rate: {
179 │       maxPerMinute: spec.rate.maxPerMinute,
180 │       maxPerHour: spec.rate.maxPerHour,
181 │       maxPerDay: spec.rate.maxPerDay,
182 │     },
183 │     bounds: {
184 │       maxToolInvocations: spec.bounds.maxToolInvocations,
185 │       maxRounds: spec.bounds.maxRounds,
186 │       maxTurnMinutes: spec.bounds.maxTurnMinutes,
187 │     },
188 │   };
189 │   return JSON.stringify(ordered);
190 │ }
191 │ 
192 │ /** Defaults a partially-filled spec (only the bounds/rate a firer may relax downward, never upward). */
193 │ export function defaultTriggerBounds(): TriggerBounds {
194 │   return {
195 │     maxToolInvocations: TRIGGER_DEFAULT_MAX_TOOL_INVOCATIONS,
196 │     maxRounds: TRIGGER_DEFAULT_MAX_ROUNDS,
197 │     maxTurnMinutes: TRIGGER_DEFAULT_MAX_TURN_MINUTES,
198 │   };
199 │ }
200 │ 
201 │ export function defaultTriggerRate(): TriggerRate {
202 │   return {
203 │     maxPerMinute: TRIGGER_DEFAULT_MAX_PER_MINUTE,
204 │     maxPerHour: TRIGGER_DEFAULT_MAX_PER_HOUR,
205 │     maxPerDay: TRIGGER_DEFAULT_MAX_PER_DAY,
206 │   };
207 │ }
208 │ 
209 │ /**
210 │  * Parse and fully validate a trigger spec. Throws on the first problem, naming it. A spec that parses here is the
211 │  * only shape a firer may accept; every rejection is an abuse surface closed at the boundary.
212 │  *
213 │  * `allowWorktreeWrite` is false by default: `worktree-write` triggers cannot be registered without the operator
214 │  * passing the explicit flag (D19 default: read-only only).
215 │  */
216 │ export function parseTriggerSpec(text: string, options?: { allowWorktreeWrite?: boolean }): TriggerSpec {
217 │   const allowWorktreeWrite = options?.allowWorktreeWrite === true;
218 │   let parsed: unknown;
219 │   try {
220 │     parsed = parseStrictJson(text, { maxDepth: 16 } satisfies StrictJsonOptions);
221 │   } catch (error) {
222 │     fail(error instanceof Error ? error.message : String(error));
223 │   }
224 │   if (!isRecord(parsed)) fail("the document is not an object");
225 │   if (parsed.format !== "nexus-trigger") fail(`format must be "nexus-trigger", got ${JSON.stringify(parsed.format)}`);
226 │   if (parsed.version !== TRIGGER_SPEC_FORMAT_VERSION)
227 │     fail(`version must be ${TRIGGER_SPEC_FORMAT_VERSION}, got ${JSON.stringify(parsed.version)}`);
228 │ 
229 │   const id = parsed.id;
230 │   if (!isString(id) || !ID_RE.test(id)) fail('id must match /^[a-z0-9][a-z0-9-]{0,62}$/');
231 │ 
232 │   const event = parsed.event;
233 │   if (!isRecord(event)) fail("event must be an object");
234 │   const kind = event.kind;
235 │   if (!isString(kind) || !TRIGGER_EVENT_KINDS.includes(kind as TriggerEventKind))
236 │     fail(`event.kind must be one of ${TRIGGER_EVENT_KINDS.join(", ")}`);
237 │ 
238 │   let paths: string[] | undefined;
239 │   if (event.paths !== undefined) {
240 │     if (!Array.isArray(event.paths) || event.paths.length === 0 || event.paths.length > TRIGGER_MAX_PATHS)
241 │       fail(`event.paths must be 1..${TRIGGER_MAX_PATHS} strings`);
242 │     paths = [];
243 │     for (const p of event.paths) {
244 │       if (!isString(p) || p.length === 0 || p.length > TRIGGER_MAX_PATH_GLOB) fail("each event.path must be 1..256 chars");
245 │       if (PATH_SEGMENT_BAD.test(p)) fail(`event.path must not contain ".." or be absolute: ${p}`);
246 │       paths.push(p);
247 │     }
248 │   }
249 │ 
250 │   let secret: string | undefined;
251 │   if (event.secret !== undefined) {
252 │     if (!isString(event.secret) || event.secret.length === 0 || event.secret.length > TRIGGER_MAX_SECRET)
253 │       fail(`event.secret must be 1..${TRIGGER_MAX_SECRET} base64url chars`);
254 │     if (!SECRET_RE.test(event.secret)) fail("event.secret must be base64url ([A-Za-z0-9_-])");
255 │     secret = event.secret;
256 │   }
257 │ 
258 │   let allowedOrigins: string[] | undefined;
259 │   if (event.allowedOrigins !== undefined) {
260 │     if (!Array.isArray(event.allowedOrigins) || event.allowedOrigins.length > TRIGGER_MAX_ORIGINS)
261 │       fail(`event.allowedOrigins must be 0..${TRIGGER_MAX_ORIGINS} strings`);
262 │     allowedOrigins = [];
263 │     for (const o of event.allowedOrigins) {
264 │       if (!isString(o) || o.length === 0 || o.length > TRIGGER_MAX_ORIGIN) fail("each origin must be 1..256 chars");
265 │       if (!ORIGIN_RE.test(o)) fail(`origin must be a host or URL, got ${JSON.stringify(o)}`);
266 │       allowedOrigins.push(o);
267 │     }
268 │   }
269 │ 
270 │   if (kind === "webhook" && secret === undefined) fail("webhook triggers require event.secret");
271 │   if (kind === "file-change" && paths === undefined) fail("file-change triggers require event.paths");
272 │   if (kind === "file-change" && secret !== undefined) fail("file-change triggers may not set event.secret");
273 │   if (kind === "webhook" && paths !== undefined) fail("webhook triggers may not set event.paths");
274 │ 
275 │   const action = parsed.action;
276 │   if (!isRecord(action)) fail("action must be an object");
277 │   const prompt = action.prompt;
278 │   if (!isString(prompt) || prompt.length === 0 || prompt.length > TRIGGER_MAX_PROMPT)
279 │     fail(`action.prompt must be 1..${TRIGGER_MAX_PROMPT} chars`);
280 │   const policy = action.policy;
281 │   if (!isString(policy) || !TRIGGER_POLICIES.includes(policy as TriggerPolicy))
282 │     fail(`action.policy must be one of ${TRIGGER_POLICIES.join(", ")}`);
283 │   if (policy === "worktree-write" && !allowWorktreeWrite)
284 │     fail("action.policy worktree-write is refused unless the operator passed --allow-worktree-write");
285 │ 
286 │   let verifier: string | undefined;
287 │   if (action.verifier !== undefined) {
288 │     if (!isString(action.verifier) || action.verifier.length === 0 || action.verifier.length > TRIGGER_MAX_RULE)
289 │       fail(`action.verifier must be 1..${TRIGGER_MAX_RULE} chars`);
290 │     verifier = action.verifier;
291 │   }
292 │ 
293 │   const rate = parsed.rate;
294 │   if (!isRecord(rate)) fail("rate must be an object");
295 │   const maxPerMinute = asBoundedInt(rate.maxPerMinute, 1, 1000, "rate.maxPerMinute");
296 │   const maxPerHour = asBoundedInt(rate.maxPerHour, 1, 10000, "rate.maxPerHour");
297 │   const maxPerDay = asBoundedInt(rate.maxPerDay, 1, 100000, "rate.maxPerDay");
298 │   if (maxPerMinute > maxPerHour) fail("rate.maxPerMinute may not exceed rate.maxPerHour");
299 │   if (maxPerHour > maxPerDay) fail("rate.maxPerHour may not exceed rate.maxPerDay");
300 │ 
301 │   const bounds = parsed.bounds;
302 │   if (!isRecord(bounds)) fail("bounds must be an object");
303 │   const maxToolInvocations = asBoundedInt(bounds.maxToolInvocations, 1, 10000, "bounds.maxToolInvocations");
304 │   const maxRounds = asBoundedInt(bounds.maxRounds, 1, 100, "bounds.maxRounds");
305 │   const maxTurnMinutes = asBoundedInt(bounds.maxTurnMinutes, 1, 4320, "bounds.maxTurnMinutes");
306 │ 
307 │   // Unknown keys are refused: a future key cannot silently broaden what a trigger does.
308 │   const known = new Set([
309 │     "format", "version", "id", "event", "action", "rate", "bounds",
310 │     "kind", "paths", "secret", "allowedOrigins", "prompt", "policy", "verifier",
311 │     "maxPerMinute", "maxPerHour", "maxPerDay", "maxToolInvocations", "maxRounds", "maxTurnMinutes",
312 │   ]);
313 │   const unknownKeys = unknownKeysOf(parsed, known);
314 │   if (unknownKeys.length) fail(`unknown keys: ${unknownKeys.join(", ")}`);
315 │   const unknownEventKeys = unknownKeysOf(event, new Set(["kind", "paths", "secret", "allowedOrigins"]));
316 │   if (unknownEventKeys.length) fail(`unknown event keys: ${unknownEventKeys.join(", ")}`);
317 │   const unknownActionKeys = unknownKeysOf(action, new Set(["prompt", "policy", "verifier"]));
318 │   if (unknownActionKeys.length) fail(`unknown action keys: ${unknownActionKeys.join(", ")}`);
319 │   const unknownRateKeys = unknownKeysOf(rate, new Set(["maxPerMinute", "maxPerHour", "maxPerDay"]));
320 │   if (unknownRateKeys.length) fail(`unknown rate keys: ${unknownRateKeys.join(", ")}`);
321 │   const unknownBoundsKeys = unknownKeysOf(bounds, new Set(["maxToolInvocations", "maxRounds", "maxTurnMinutes"]));
322 │   if (unknownBoundsKeys.length) fail(`unknown bounds keys: ${unknownBoundsKeys.join(", ")}`);
323 │ 
324 │   return {
325 │     format: "nexus-trigger",
326 │     version: TRIGGER_SPEC_FORMAT_VERSION,
327 │     id,
328 │     event: { kind: kind as TriggerEventKind, ...(paths !== undefined ? { paths } : {}), ...(secret !== undefined ? { secret } : {}), ...(allowedOrigins !== undefined ? { allowedOrigins } : {}) },
329 │     action: { prompt, policy: policy as TriggerPolicy, ...(verifier !== undefined ? { verifier } : {}) },
330 │     rate: { maxPerMinute, maxPerHour, maxPerDay },
331 │     bounds: { maxToolInvocations, maxRounds, maxTurnMinutes },
332 │   };
333 │ }
334 │ 
335 │ function asBoundedInt(value: unknown, min: number, max: number, what: string): number {
336 │   if (typeof value !== "number" || !Number.isInteger(value) || value < min || value > max)
337 │     fail(`${what} must be an integer ${min}..${max}`);
338 │   return value;
339 │ }
340 │ 
341 │ function unknownKeysOf(obj: Record<string, unknown>, known: Set<string>): string[] {
342 │   const found: string[] = [];
343 │   for (const key of Object.keys(obj)) if (!known.has(key)) found.push(key);
344 │   return found.sort();
345 │ }
346 │ 
347 │ /**
348 │  * Whether a stored approval still matches the current spec bytes. Mirrors content_trust.ts status semantics.
349 │  */
350 │ export function triggerTrustStatus(
351 │   entries: readonly TriggerTrustEntry[],
352 │   id: string,
353 │   scope: string,
354 │   currentSha256: string | undefined,
355 │ ): TriggerTrustStatus {
356 │   const stored = entries.find((e) => e.kind === "trigger" && e.scope === scope && e.key === id);
357 │   if (currentSha256 === undefined) return stored ? "REMOVED" : "ABSENT";
358 │   if (!stored) return "NEW";
359 │   return stored.sha256 === currentSha256 ? "MATCH" : "MISMATCH";
360 │ }
361 │ 
362 │ /** Reads the trigger trust store. A missing or malformed store holds no approvals and never fails open. */
363 │ export function readTriggerTrustStore(storePath: string): { entries: TriggerTrustEntry[]; problem?: string } {
364 │   try {
365 │     if (!fs.existsSync(storePath)) return { entries: [] };
366 │     const stat = fs.statSync(storePath);
367 │     if (!stat.isFile() || (stat.mode & 0o077) !== 0) return { entries: [], problem: "the trigger trust store is not a private regular file" };
368 │     const bytes = fs.readFileSync(storePath);
369 │     if (bytes.length > 256 * 1024) return { entries: [], problem: "the trigger trust store is too large" };
370 │     const parsed = parseStrictJson(bytes.toString("utf8"), { maxDepth: 16 });
371 │     if (!isRecord(parsed) || parsed.version !== 1 || !Array.isArray(parsed.entries))
372 │       return { entries: [], problem: "it is not a version 1 trigger trust store" };
373 │     const entries: TriggerTrustEntry[] = [];
374 │     for (const raw of parsed.entries) {
375 │       const entry = triggerTrustEntryOf(raw);
376 │       if (!entry) return { entries: [], problem: "it has a malformed entry" };
377 │       entries.push(entry);
378 │     }
379 │     return { entries };
380 │   } catch (error) {
381 │     return { entries: [], problem: error instanceof Error ? error.message : String(error) };
382 │   }
383 │ }
384 │ 
385 │ export function triggerTrustEntryOf(raw: unknown): TriggerTrustEntry | undefined {
386 │   if (!isRecord(raw)) return undefined;
387 │   const { kind, scope, key, sha256, approvedAt, summary } = raw;
388 │   if (kind !== "trigger") return undefined;
389 │   if (typeof scope !== "string" || typeof key !== "string" || !ID_RE.test(key)) return undefined;
390 │   if (typeof sha256 !== "string" || !/^[0-9a-f]{64}$/.test(sha256)) return undefined;
391 │   if (typeof approvedAt !== "string" || typeof summary !== "string" || summary.length === 0 || summary.length > 200)
392 │     return undefined;
393 │   return { kind, scope, key, sha256, approvedAt, summary };
394 │ }

