  1 │ /**
  2 │  * BG-3 trust and abuse model: the trigger trust store.
  3 │  *
  4 │  * Approvals of trigger specs are keyed by the SHA-256 of their exact bytes (`~/.config/nexus/trigger_trust.json`),
  5 │  * mirroring content_trust.ts (extension approvals). An approval names one spec: changed bytes are a different spec
  6 │  * and are not approved. A store that cannot be read safely or is malformed holds no approvals; it never fails open.
  7 │  *
  8 │  * Trust surface covered:
  9 │  *   - only a workspace the operator trusts (workspace_trust.ts) may have triggers
 10 │  *   - approving a trigger is the act of a person at a terminal (no `--yes`, no programmatic approval)
 11 │  *   - a trigger spec's bytes are pinned by hash; MISMATCH / REMOVED means the spec is not in force
 12 │  *
 13 │  * Abuse surface covered:
 14 │  *   - rate caps live on the spec (trigger_spec.ts) and are enforced by trigger_rate_limit.ts
 15 │  *   - GG-3: a trigger cannot approve a denied action, raise a verdict, widen a policy tier or remove a
 16 │  *     verification-file protection; triggers run unattended (see unattended.ts)
 17 │  */
 18 │ 
 19 │ import * as fs from "node:fs";
 20 │ import * as os from "node:os";
 21 │ import * as path from "node:path";
 22 │ import {
 23 │   type TriggerSpec,
 24 │   type TriggerTrustEntry,
 25 │   type TriggerTrustStatus,
 26 │   triggerSpecSha256,
 27 │   triggerTrustEntryOf,
 28 │   triggerTrustStatus,
 29 │   type TriggerTrustStore,
 30 │   canonicalizeTriggerSpec,
 31 │ } from "./trigger_spec.js";
 32 │ import { writePrivateFile } from "./durable_file.js";
 33 │ import { decodeStrictUtf8, parseStrictJson, readHardenedFile } from "./strict_json.js";
 34 │ import { isWorkspaceTrusted } from "../workspace_trust.js";
 35 │ 
 36 │ export const TRIGGER_TRUST_VERSION = 1;
 37 │ const STORE_LIMIT = 256 * 1024;
 38 │ 
 39 │ export interface TriggerTrustStoreDoc {
 40 │   version: 1;
 41 │   entries: TriggerTrustEntry[];
 42 │ }
 43 │ 
 44 │ export type TriggerTrustId = Pick<TriggerTrustEntry, "scope" | "key">;
 45 │ 
 46 │ export function triggerTrustStorePath(): string {
 47 │   return path.join(os.homedir(), ".config", "nexus", "trigger_trust.json");
 48 │ }
 49 │ 
 50 │ const isRecord = (value: unknown): value is Record<string, unknown> =>
 51 │   Boolean(value) && typeof value === "object" && !Array.isArray(value);
 52 │ 
 53 │ function sameTriggerId(a: TriggerTrustId, b: TriggerTrustId): boolean {
 54 │   return a.scope === b.scope && a.key === b.key;
 55 │ }
 56 │ 
 57 │ /** The approvals in the store. A missing store is empty; a non-private, oversized, version-mismatched or
 58 │  * malformed store holds no approvals and `problem` says why. */
 59 │ export function readTriggerTrustStore(storePath = triggerTrustStorePath()): {
 60 │   entries: TriggerTrustEntry[];
 61 │   problem?: string;
 62 │ } {
 63 │   try {
 64 │     if (!fs.existsSync(storePath)) return { entries: [] };
 65 │     const file = readHardenedFile(storePath, { maxBytes: STORE_LIMIT, forbiddenMode: 0o077 });
 66 │     if (!file) return { entries: [] };
 67 │     const parsed = parseStrictJson(decodeStrictUtf8(file.bytes));
 68 │     if (!isRecord(parsed) || parsed.version !== TRIGGER_TRUST_VERSION || !Array.isArray(parsed.entries))
 69 │       return { entries: [], problem: "it is not a version 1 trigger trust store" };
 70 │     const entries: TriggerTrustEntry[] = [];
 71 │     for (const raw of parsed.entries) {
 72 │       const entry = triggerTrustEntryOf(raw);
 73 │       if (!entry) return { entries: [], problem: "it has a malformed entry" };
 74 │       entries.push(entry);
 75 │     }
 76 │     return { entries };
 77 │   } catch (error) {
 78 │     return { entries: [], problem: error instanceof Error ? error.message : String(error) };
 79 │   }
 80 │ }
 81 │ 
 82 │ /** The approval recorded for `id` in `scope`, if any. */
 83 │ export function triggerTrustEntry(
 84 │   entries: readonly TriggerTrustEntry[],
 85 │   id: TriggerTrustId,
 86 │ ): TriggerTrustEntry | undefined {
 87 │   return entries.find((entry) => sameTriggerId(entry, id));
 88 │ }
 89 │ 
 90 │ /**
 91 │  * How `currentSha256` (undefined: there is no spec file now) stands against the approval recorded for `id` in `scope`.
 92 │  * Delegates to trigger_spec.ts's `triggerTrustStatus`.
 93 │  */
 94 │ 
 95 │ function write(storePath: string, entries: TriggerTrustEntry[]): void {
 96 │   const store: TriggerTrustStoreDoc = { version: TRIGGER_TRUST_VERSION, entries };
 97 │   writePrivateFile(storePath, `${JSON.stringify(store, null, 2)}\n`, { durable: true });
 98 │ }
 99 │ 
100 │ /**
101 │  * Records the approval of exactly `entry.sha256`, replacing an earlier approval of the same item. Refuses to approve
102 │  * a trigger for a workspace the operator has not trusted: a workspace that is not in the trust store and has no
103 │  * `NEXUS_TRUST_WORKSPACE=1` cannot run triggers.
104 │  */
105 │ export function approveTrigger(
106 │   entry: TriggerTrustEntry,
107 │   options: { workspaceTrusted: boolean; storePath?: string },
108 │ ): void {
109 │   if (!options.workspaceTrusted)
110 │     throw new Error(`approveTrigger: the workspace ${entry.scope} is not trusted; triggers cannot be registered there`);
111 │   if (!triggerTrustEntryOf(entry))
112 │     throw new Error("approveTrigger: the entry is not a valid approval (sha256 must be 64 lowercase hexadecimal digits)");
113 │   const storePath = options.storePath ?? triggerTrustStorePath();
114 │   const kept = readTriggerTrustStore(storePath).entries.filter((other) => !sameTriggerId(other, entry));
115 │   write(storePath, [...kept, entry]);
116 │ }
117 │ 
118 │ /** Removes the approval of `id` in `scope`. Returns whether there was one. */
119 │ export function revokeTrigger(
120 │   id: TriggerTrustId,
121 │   storePath = triggerTrustStorePath(),
122 │ ): boolean {
123 │   const { entries } = readTriggerTrustStore(storePath);
124 │   const kept = entries.filter((other) => !sameTriggerId(other, id));
125 │   if (kept.length === entries.length) return false;
126 │   write(storePath, kept);
127 │   return true;
128 │ }
129 │ 
130 │ /** Builds a trust entry for a spec: the SHA-256 of its canonical bytes plus a one-line summary. */
131 │ export function entryForSpec(
132 │   scope: string,
133 │   spec: TriggerSpec,
134 │   approvedAt: string,
135 │ ): TriggerTrustEntry {
136 │   return {
137 │     kind: "trigger",
138 │     scope,
139 │     key: spec.id,
140 │     sha256: triggerSpecSha256(Buffer.from(canonicalizeTriggerSpec(spec), "utf8")),
141 │     approvedAt,
142 │     summary: `${spec.event.kind} trigger ${spec.id} (${spec.action.policy}, ${spec.bounds.maxToolInvocations} tool invocations max)`,
143 │   };
144 │ }
145 │ 
146 │ /** Whether the workspace at `workspace` may have triggers approved for it (the operator's trust decision). */
147 │ export function workspaceMayHaveTriggers(workspace: string): boolean {
148 │   return isWorkspaceTrusted(workspace, false);
149 │ }
150 │ 
151 │ /** The trust decision shown beside a trigger: the workspace is trusted or it is not. */
152 │ export interface TriggerTrustDecision {
153 │   /** MATCH: the spec is approved and unchanged. */
154 │   status: TriggerTrustStatus;
155 │   /** The approval record, if any. */
156 │   entry?: TriggerTrustEntry;
157 │   /** Why the trigger may or may not run. */
158 │   reason: string;
159 │   /** The workspace trust fact. */
160 │   workspaceTrusted: boolean;
161 │ }
162 │ 
163 │ /** The trust decision for a trigger in a workspace, from the entries and the current spec bytes. */
164 │ export function decideTriggerTrust(
165 │   entries: readonly TriggerTrustEntry[],
166 │   workspace: string,
167 │   spec: TriggerSpec | undefined,
168 │   currentSha256: string | undefined,
169 │ ): TriggerTrustDecision {
170 │   const workspaceTrusted = workspaceMayHaveTriggers(workspace);
171 │   const id: TriggerTrustId = { scope: workspace, key: spec ? spec.id : "" };
172 │   const status = spec ? triggerTrustStatus(entries, id.key, id.scope, currentSha256) : "ABSENT";
173 │   const entry = triggerTrustEntry(entries, id);
174 │ 
175 │   let reason: string;
176 │   if (!workspaceTrusted) reason = "the workspace is not trusted; triggers cannot run there";
177 │   else if (status === "NEW") reason = "the trigger spec is not approved; run `nexus triggers approve` in a terminal";
178 │   else if (status === "MISMATCH")
179 │     reason = "the trigger spec changed since it was approved; it needs a new approval";
180 │   else if (status === "REMOVED") reason = "the trigger spec was removed; its approval no longer applies";
181 │   else if (status === "ABSENT")
182 │     reason = "there is no trigger spec and no approval";
183 │   else reason = "the trigger spec is approved and unchanged";
184 │ 
185 │   return { status, entry, reason, workspaceTrusted };
186 │ }
187 │ 
188 │ /** Whether a trigger may run right now: trusted workspace + MATCH status. */
189 │ export function triggerMayRun(decision: TriggerTrustDecision): boolean {
190 │   return decision.workspaceTrusted && decision.status === "MATCH" && Boolean(decision.entry);
191 │ }

