  1 │ /**
  2 │  * BG-3 trust and abuse model: the trigger trust store.
  3 │  *
  4 │  * Approvals of trigger specs are keyed by the SHA-256 of their exact bytes (`~/.config/nexus/trigger_trust.json`),
  5 │  * mirroring content_trust.ts (extension approvals). An approval names one spec: changed bytes are a different spec
  6 │  * and are not approved. A store that cannot be read safely or is malformed holds no approvals; it never fails open.
  7 │  *
  8 │  * Trust surface covered:
  9 │  *   - only a workspace the operator trusts (workspace_trust.ts) may have triggers
 10 │  *   - approving a trigger is the act of a person at a terminal (no `--yes`, no programmatic approval)
 11 │  *   - a trigger spec's bytes are pinned by hash; MISMATCH / REMOVED means the spec is not in force
 12 │  *
 13 │  * Abuse surface covered:
 14 │  *   - rate caps live on the spec (trigger_spec.ts) and are enforced by trigger_rate_limit.ts
 15 │  *   - GG-3: a trigger cannot approve a denied action, raise a verdict, widen a policy tier or remove a
 16 │  *     verification-file protection; triggers run unattended (see unattended.ts)
 17 │  */
 18 │ 
 19 │ import * as fs from "node:fs";
 20 │ import * as os from "node:os";
 21 │ import * as path from "node:path";
 22 │ import {
 23 │   type TriggerSpec,
 24 │   type TriggerTrustEntry,
 25 │   type TriggerTrustStatus,
 26 │   triggerSpecSha256,
 27 │   triggerTrustEntryOf,
 28 │   triggerTrustStatus,
 29 │   type TriggerTrustStore,
 30 │   canonicalizeTriggerSpec,
 31 │ } from "./trigger_spec.js";
 32 │ import { writePrivateFile } from "./durable_file.js";
 33 │ import { decodeStrictUtf8, parseStrictJson, readHardenedFile } from "./strict_json.js";
 34 │ import { isWorkspaceTrusted } from "../workspace_trust.js";
 35 │ 
 36 │ export const TRIGGER_TRUST_VERSION = 1;
 37 │ const STORE_LIMIT = 256 * 1024;
 38 │ 
 39 │ export interface TriggerTrustStoreDoc {
 40 │   version: 1;
 41 │   entries: TriggerTrustEntry[];
 42 │ }
 43 │ 
 44 │ export type TriggerTrustId = Pick<TriggerTrustEntry, "scope" | "key">;
 45 │ 
 46 │ export function triggerTrustStorePath(): string {
 47 │   return path.join(os.homedir(), ".config", "nexus", "trigger_trust.json");
 48 │ }
 49 │ 
 50 │ const isRecord = (value: unknown): value is Record<string, unknown> =>
 51 │   Boolean(value) && typeof value === "object" && !Array.isArray(value);
 52 │ 
 53 │ function sameTriggerId(a: TriggerTrustId, b: TriggerTrustId): boolean {
 54 │   return a.scope === b.scope && a.key === b.key;
 55 │ }
 56 │ 
 57 │ /** The approvals in the store. A missing store is empty; a non-private, oversized, version-mismatched or
 58 │  * malformed store holds no approvals and `problem` says why. */
 59 │ export function readTriggerTrustStore(storePath = triggerTrustStorePath()): {
 60 │   entries: TriggerTrustEntry[];
 61 │   problem?: string;
 62 │ } {
 63 │   try {
 64 │     if (!fs.existsSync(storePath)) return { entries: [] };
 65 │     const file = readHardenedFile(storePath, { maxBytes: STORE_LIMIT, forbiddenMode: 0o077 });
 66 │     if (!file) return { entries: [] };
 67 │     const parsed = parseStrictJson(decodeStrictUtf8(file.bytes));
 68 │     if (!isRecord(parsed) || parsed.version !== TRIGGER_TRUST_VERSION || !Array.isArray(parsed.entries))
 69 │       return { entries: [], problem: "it is not a version 1 trigger trust store" };
 70 │     const entries: TriggerTrustEntry[] = [];
 71 │     for (const raw of parsed.entries) {
 72 │       const entry = triggerTrustEntryOf(raw);
 73 │       if (!entry) return { entries: [], problem: "it has a malformed entry" };
 74 │       entries.push(entry);
 75 │     }
 76 │     return { entries };
 77 │   } catch (error) {
 78 │     return { entries: [], problem: error instanceof Error ? error.message : String(error) };
 79 │   }
 80 │ }
 81 │ 
 82 │ /** The approval recorded for `id` in `scope`, if any. */
 83 │ export function triggerTrustEntry(
 84 │   entries: readonly TriggerTrustEntry[],
 85 │   id: TriggerTrustId,
 86 │ ): TriggerTrustEntry | undefined {
 87 │   return entries.find((entry) => sameTriggerId(entry, id));
 88 │ }
 89 │ 
 90 │ /**
 91 │  * How `currentSha256` (undefined: there is no spec file now) stands against the approval recorded for `id` in `scope`.
 92 │  * Delegates to trigger_spec.ts's `triggerTrustStatus`.
 93 │  */
 94 │ 
 95 │ function write(storePath: string, entries: TriggerTrustEntry[]): void {
 96 │   const store: TriggerTrustStoreDoc = { version: TRIGGER_TRUST_VERSION, entries };
 97 │   writePrivateFile(storePath, `${JSON.stringify(store, null, 2)}\n`, { durable: true });
 98 │ }
 99 │ 
100 │ /**
101 │  * Records the approval of exactly `entry.sha256`, replacing an earlier approval of the same item. Refuses to approve
102 │  * a trigger for a workspace the operator has not trusted: a workspace that is not in the trust store and has no
103 │  * `NEXUS_TRUST_WORKSPACE=1` cannot run triggers.
104 │  */
105 │ export function approveTrigger(
106 │   entry: TriggerTrustEntry,
107 │   options: { workspaceTrusted: boolean; storePath?: string },
108 │ ): void {
109 │   if (!options.workspaceTrusted)
110 │     throw new Error(`approveTrigger: the workspace ${entry.scope} is not trusted; triggers cannot be registered there`);
111 │   if (!triggerTrustEntryOf(entry))
112 │     throw new Error("approveTrigger: the entry is not a valid approval (sha256 must be 64 lowercase hexadecimal digits)");
113 │   const storePath = options.storePath ?? triggerTrustStorePath();
114 │   const kept = readTriggerTrustStore(storePath).entries.filter((other) => !sameTriggerId(other, entry));
115 │   write(storePath, [...kept, entry]);
116 │ }
117 │ 
118 │ /** Removes the approval of `id` in `scope`. Returns whether there was one. */
119 │ export function revokeTrigger(
120 │   id: TriggerTrustId,
121 │   storePath = triggerTrustStorePath(),
122 │ ): boolean {
123 │   const { entries } = readTriggerTrustStore(storePath);
124 │   const kept = entries.filter((other) => !sameTriggerId(other, id));
125 │   if (kept.length === entries.length) return false;
126 │   write(storePath, kept);
127 │   return true;
128 │ }
129 │ 
130 │ /** Builds a trust entry for a spec: the SHA-256 of its canonical bytes plus a one-line summary. */
131 │ export function entryForSpec(
132 │   scope: string,
133 │   spec: TriggerSpec,
134 │   approvedAt: string,
135 │ ): TriggerTrustEntry {
136 │   return {
137 │     kind: "trigger",
138 │     scope,
139 │     key: spec.id,
140 │     sha256: triggerSpecSha256(Buffer.from(canonicalizeTriggerSpec(spec), "utf8")),
141 │     approvedAt,
142 │     summary: `${spec.event.kind} trigger ${spec.id} (${spec.action.policy}, ${spec.bounds.maxToolInvocations} tool invocations max)`,
143 │   };
144 │ }
145 │ 
146 │ /** Whether the workspace at `workspace` may have triggers approved for it (the operator's trust decision). */
147 │ export function workspaceMayHaveTriggers(workspace: string): boolean {
148 │   return isWorkspaceTrusted(workspace, false);
149 │ }
150 │ 
151 │ /** The trust decision shown beside a trigger: the workspace is trusted or it is not. */
152 │ export interface TriggerTrustDecision {
153 │   /** MATCH: the spec is approved and unchanged. */
154 │   status: TriggerTrustStatus;
155 │   /** The approval record, if any. */
156 │   entry?: TriggerTrustEntry;
157 │   /** Why the trigger may or may not run. */
158 │   reason: string;
159 │   /** The workspace trust fact. */
160 │   workspaceTrusted: boolean;
161 │ }
162 │ 
163 │ /** The trust decision for a trigger in a workspace, from the entries and the current spec bytes. */
164 │ export function decideTriggerTrust(
165 │   entries: readonly TriggerTrustEntry[],
166 │   workspace: string,
167 │   spec: TriggerSpec | undefined,
168 │   currentSha256: string | undefined,
169 │ ): TriggerTrustDecision {
170 │   const workspaceTrusted = workspaceMayHaveTriggers(workspace);
171 │   const id: TriggerTrustId = { scope: workspace, key: spec ? spec.id : "" };
172 │   const status = spec ? triggerTrustStatus(entries, id.key, id.scope, currentSha256) : "ABSENT";
173 │   const entry = triggerTrustEntry(entries, id);
174 │ 
175 │   let reason: string;
176 │   if (!workspaceTrusted) reason = "the workspace is not trusted; triggers cannot run there";
177 │   else if (status === "NEW") reason = "the trigger spec is not approved; run `nexus triggers approve` in a terminal";
178 │   else if (status === "MISMATCH")
179 │     reason = "the trigger spec changed since it was approved; it needs a new approval";
180 │   else if (status === "REMOVED") reason = "the trigger spec was removed; its approval no longer applies";
181 │   else if (status === "ABSENT")
182 │     reason = "there is no trigger spec and no approval";
183 │   else reason = "the trigger spec is approved and unchanged";
184 │ 
185 │   return { status, entry, reason, workspaceTrusted };
186 │ }
187 │ 
188 │ /** Whether a trigger may run right now: trusted workspace + MATCH status. */
189 │ export function triggerMayRun(decision: TriggerTrustDecision): boolean {
190 │   return decision.workspaceTrusted && decision.status === "MATCH" && Boolean(decision.entry);
191 │ }

content.content:
  1 │ /**
  2 │  * `nexus triggers`: list trigger trust status, approve or revoke a workspace's trigger specs (BG-3 trust model).
  3 │  *
  4 │  * Approving a trigger is the act of a person at a terminal: there is no `--yes`, and without a terminal nothing is
  5 │  * approved. A trigger spec's bytes are pinned by SHA-256; changed bytes are a different spec and need a new approval.
  6 │  *
  7 │  * BG-3 itself (the trigger firer that watches files and HTTP) is deferred to v1.4. This CLI is the trust surface it
  8 │  * builds on: `nexus triggers list` shows what is approved and what is not, `approve` pins a spec by hash, `revoke`
  9 │  * withdraws approval. A firer reads `triggerMayRun` from trigger_trust.ts before starting any run.
 10 │  */
 11 │ 
 12 │ import * as fs from "node:fs";
 13 │ import * as path from "node:path";
 14 │ import type { Command } from "commander";
 15 │ import pc from "picocolors";
 16 │ import { createHash } from "node:crypto";
 17 │ import { parseStrictJson, readHardenedFile, decodeStrictUtf8 } from "./core/strict_json.js";
 18 │ import { writePrivateFile } from "./core/durable_file.js";
 19 │ import {
 20 │   triggerTrustStorePath,
 21 │   readTriggerTrustStore,
 22 │   approveTrigger,
 23 │   revokeTrigger,
 24 │   triggerTrustEntry,
 25 │   entryForSpec,
 26 │   triggerMayRun,
 27 │   workspaceMayHaveTriggers,
 28 │   decideTriggerTrust,
 29 │ } from "./core/trigger_trust.js";
 30 │ import {
 31 │   parseTriggerSpec,
 32 │   canonicalizeTriggerSpec,
 33 │   triggerSpecSha256,
 34 │   type TriggerSpec,
 35 │   type TriggerTrustEntry,
 36 │ } from "./core/trigger_spec.js";
 37 │ import { realWorkspace } from "./workspace_trust.js";
 38 │ import { hookLine } from "./core/hook_runner.js";
 39 │ 
 40 │ export interface TriggersCliDeps {
 41 │   /** Asks a yes/no question on the terminal. */
 42 │   confirm?: (question: string) => Promise<boolean>;
 43 │   /** Whether there is a terminal to ask on. */
 44 │   interactive?: () => boolean;
 45 │ }
 46 │ 
 47 │ async function confirmOnTerminal(question: string): Promise<boolean> {
 48 │   const readline = await import("node:readline/promises");
 49 │   const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
 50 │   try {
 51 │     return /^y(es)?$/i.test((await rl.question(question)).trim());
 52 │   } finally {
 53 │     rl.close();
 54 │   }
 55 │ }
 56 │ 
 57 │ const workspaceOf = (options: { workspace?: string }) => path.resolve(options.workspace ?? process.cwd());
 58 │ 
 59 │ /** One trigger as `nexus triggers list` shows it. */
 60 │ interface ListedTrigger {
 61 │   id: string;
 62 │   kind: string;
 63 │   policy: string;
 64 │   status: "approved" | "not_approved" | "changed" | "absent";
 65 │   sha256?: string;
 66 │   problem?: string;
 67 │   bounds: string;
 68 │ }
 69 │ 
 70 │ function parseTriggerFile(file: string): { specs: TriggerSpec[]; problem?: string; rawSha256?: string } {
 71 │   try {
 72 │     if (!fs.existsSync(file)) return { specs: [], problem: undefined };
 73 │     const stat = fs.statSync(file);
 74 │     if (!stat.isFile() || (stat.mode & 0o077) !== 0)
 75 │       return { specs: [], problem: "the trigger spec file is not a private regular file" };
 76 │     const fileData = readHardenedFile(file, { maxBytes: 256 * 1024, forbiddenMode: 0o077 });
 77 │     if (!fileData) return { specs: [], problem: undefined };
 78 │     const parsed = parseStrictJson(decodeStrictUtf8(fileData.bytes));
 79 │     if (!isRecord(parsed) || parsed.version !== 1 || !Array.isArray(parsed.triggers))
 80 │       return { specs: [], problem: "it is not a version 1 trigger spec file" };
 81 │     const specs: TriggerSpec[] = [];
 82 │     for (const raw of parsed.triggers) {
 83 │       try {
 84 │         specs.push(parseTriggerSpec(JSON.stringify(raw)));
 85 │       } catch (error) {
 86 │         return { specs, problem: error instanceof Error ? error.message : String(error) };
 87 │       }
 88 │     }
 89 │     return { specs, rawSha256: createHash("sha256").update(fileData.bytes).digest("hex") };
 90 │   } catch (error) {
 91 │     return { specs: [], problem: error instanceof Error ? error.message : String(error) };
 92 │   }
 93 │ }
 94 │ 
 95 │ function isRecord(value: unknown): value is Record<string, unknown> {
 96 │   return Boolean(value) && typeof value === "object" && !Array.isArray(value);
 97 │ }
 98 │ 
 99 │ function boundsText(spec: TriggerSpec): string {
100 │   return `${spec.bounds.maxToolInvocations} tools / ${spec.bounds.maxRounds} rounds / ${spec.bounds.maxTurnMinutes} min`;
101 │ }
102 │ 
103 │ function listTriggers(workspace: string, entries: TriggerTrustEntry[]): ListedTrigger[] {
104 │   const triggerFile = path.join(workspace, ".nexus", "triggers.json");
105 │   const parsed = parseTriggerFile(triggerFile);
106 │   if (parsed.problem) return [{ id: triggerFile, kind: "—", policy: "—", status: "absent", problem: parsed.problem, bounds: "—" }];
107 │   const listed: ListedTrigger[] = [];
108 │   for (const spec of parsed.specs) {
109 │     const id: { scope: string; key: string } = { scope: realWorkspace(workspace), key: spec.id };
110 │     const entry = triggerTrustEntry(entries, id);
111 │     const currentSha256 = parsed.rawSha256;
112 │     // status is per spec: compare each spec's own hash
113 │     const specSha = triggerSpecSha256(Buffer.from(canonicalizeTriggerSpec(spec), "utf8"));
114 │     let status: ListedTrigger["status"] = "not_approved";
115 │     if (!entry) status = "not_approved";
116 │     else if (entry.sha256 === specSha) status = "approved";
117 │     else status = "changed";
118 │     listed.push({
119 │       id: spec.id,
120 │       kind: spec.event.kind,
121 │       policy: spec.action.policy,
122 │       status,
123 │       sha256: entry?.sha256,
124 │       bounds: boundsText(spec),
125 │     });
126 │   }
127 │   return listed;
128 │ }
129 │ 
130 │ function printTrigger(entry: ListedTrigger): void {
131 │   const colour = entry.status === "approved" ? pc.green : entry.status === "changed" ? pc.yellow : pc.dim;
132 │   console.log(`${pc.bold(entry.id)}  ${entry.kind}  ${entry.policy}  ${colour(entry.status)}${entry.sha256 ? pc.dim(`  sha256 ${entry.sha256}`) : ""}  ${entry.bounds}`);
133 │   if (entry.problem) console.log(`  ${pc.red(hookLine(entry.problem))}`);
134 │ }
135 │ 
136 │ export function registerTriggerCommands(program: Command, deps: TriggersCliDeps = {}): void {
137 │   const confirm = deps.confirm ?? confirmOnTerminal;
138 │   const interactive = deps.interactive ?? (() => {
139 │     const stdin = process.stdin;
140 │     const stdout = process.stdout;
141 │     return Boolean(stdin.isTTY) && Boolean(stdout.isTTY);
142 │   });
143 │ 
144 │   const triggers = program.command("triggers").description("Event trigger trust status and approvals (BG-3; firing deferred to v1.4)");
145 │ 
146 │   triggers
147 │     .command("list")
148 │     .description("Show this workspace's trigger specs and whether each is approved")
149 │     .option("-w, --workspace <path>", "Workspace directory (default: current directory)")
150 │     .option("-j, --json", "Print the listing as JSON")
151 │     .action((options: { workspace?: string; json?: boolean }) => {
152 │       const workspace = workspaceOf(options);
153 │       const entries = readTriggerTrustStore().entries;
154 │       const trusted = workspaceMayHaveTriggers(workspace);
155 │       const listed = listTriggers(workspace, entries);
156 │       if (options.json) {
157 │         console.log(JSON.stringify({ workspace, trusted, triggers: listed }, null, 2));
158 │       } else {
159 │         console.log(`Workspace: ${workspace}`);
160 │         console.log(`Trusted for triggers: ${trusted ? "yes" : "no"}`);
161 │         if (!trusted) console.log(pc.yellow("  Trust it with `nexus trust <workspace>` before any trigger can run here."));
162 │         if (!listed.length) {
163 │           console.log("  (no trigger specs in .nexus/triggers.json)");
164 │         }
165 │         for (const entry of listed) printTrigger(entry);
166 │       }
167 │     });
168 │ 
169 │   triggers
170 │     .command("approve")
171 │     .description("Approve this workspace's .nexus/triggers.json as it is now (a later change needs a new approval)")
172 │     .option("-w, --workspace <path>", "Workspace directory (default: current directory)")
173 │     .option("--sha256 <hex>", "Approve only if the file has this SHA-256 (you are still asked; approving needs a terminal)")
174 │     .action(async (options: { workspace?: string; sha256?: string }) => {
175 │       const workspace = workspaceOf(options);
176 │       const refuse = (message: string, code = 1) => {
177 │         console.error(pc.red(message));
178 │         process.exitCode = code;
179 │       };
180 │       const triggerFile = path.join(workspace, ".nexus", "triggers.json");
181 │       const parsed = parseTriggerFile(triggerFile);
182 │       if (!parsed.specs.length) return refuse(`There is no usable trigger spec in ${triggerFile}${parsed.problem ? ": " + parsed.problem : ""}.`);
183 │       if (!workspaceMayHaveTriggers(workspace))
184 │         return refuse(`Not approved: ${workspace} is not trusted for triggers. Run \`nexus trust ${workspace}\` first.`, 2);
185 │ 
186 │       const rawSha256 = parsed.rawSha256 ?? "";
187 │       console.log(`${triggerFile}\nsha256 ${rawSha256}\nThese triggers would run when their events fire:`);
188 │       for (const spec of parsed.specs) {
189 │         console.log(`  ${spec.event.kind}  ${pc.bold(spec.id)}  policy: ${spec.action.policy}  ${boundsText(spec)}`);
190 │         console.log(`    ${hookLine(spec.action.prompt, 100)}`);
191 │       }
192 │ 
193 │       // Approving is the act of a person: a tool call of the agent has no terminal.
194 │       if (!interactive()) {
195 │         return refuse("Not approved: approving triggers needs a person at a terminal (standard input and output are not both a terminal). Review the file, then run `nexus triggers approve` yourself in a terminal.", 2);
196 │       }
197 │       const pinned = options.sha256?.trim().toLowerCase();
198 │       if (pinned !== undefined && pinned !== rawSha256)
199 │         return refuse(`Not approved: --sha256 does not match the file, whose SHA-256 is ${rawSha256}.`, 2);
200 │       if (!(await confirm("Approve these triggers for this workspace? [y/N] "))) return refuse("Not approved.", 0);
201 │ 
202 │       const now = new Date().toISOString();
203 │       const storePath = triggerTrustStorePath();
204 │       const kept = readTriggerTrustStore(storePath).entries;
205 │       for (const spec of parsed.specs) {
206 │         const entry = entryForSpec(realWorkspace(workspace), spec, now);
207 │         const index = kept.findIndex((e) => e.scope === entry.scope && e.key === entry.key);
208 │         if (index !== -1) kept[index] = entry; else kept.push(entry);
209 │       }
210 │       writePrivateFile(storePath, `${JSON.stringify({ version: 1, entries: kept }, null, 2)}\n`, { durable: true });
211 │       console.log(`Approved ${parsed.specs.length} trigger${parsed.specs.length === 1 ? "" : "s"} for ${realWorkspace(workspace)}. Undo with \`nexus triggers revoke\`.`);
212 │     });
213 │ 
214 │   triggers
215 │     .command("revoke")
216 │     .description("Withdraw the approval of a trigger in this workspace")
217 │     .argument("<id>", "Trigger id to revoke")
218 │     .option("-w, --workspace <path>", "Workspace directory (default: current directory)")
219 │     .action((id: string, options: { workspace?: string }) => {
220 │       const workspace = workspaceOf(options);
221 │       const removed = revokeTrigger({ scope: realWorkspace(workspace), key: id });
222 │       console.log(removed ? `No longer approved: trigger ${id}` : `There was no approval for trigger ${id}.`);
223 │     });
224 │ 
225 │   triggers
226 │     .command("status")
227 │     .description("Show the trust decision for one trigger (whether it may run now)")
228 │     .argument("<id>", "Trigger id")
229 │     .option("-w, --workspace <path>", "Workspace directory (default: current directory)")
230 │     .action((id: string, options: { workspace?: string }) => {
231 │       const workspace = workspaceOf(options);
232 │       const triggerFile = path.join(workspace, ".nexus", "triggers.json");
233 │       const parsed = parseTriggerFile(triggerFile);
234 │       const spec = parsed.specs.find((s) => s.id === id);
235 │       const currentSha256 = spec ? triggerSpecSha256(Buffer.from(canonicalizeTriggerSpec(spec), "utf8")) : undefined;
236 │       const entries = readTriggerTrustStore().entries;
237 │       const decision = decideTriggerTrust(entries, realWorkspace(workspace), spec, currentSha256);
238 │       console.log(`trigger ${id} in ${workspace}`);
239 │       console.log(`  trusted: ${decision.workspaceTrusted ? "yes" : "no"}`);
240 │       console.log(`  status: ${decision.status}`);
241 │       console.log(`  may run: ${triggerMayRun(decision) ? "yes" : "no"}`);
242 │       console.log(`  ${decision.reason}`);
243 │       process.exitCode = triggerMayRun(decision) ? 0 : 1;
244 │     });
245 │ }
  1 │ /**
  2 │  * A strict, bounded JSON reader for files that decide what runs (hook declarations, the extension trust store):
  3 │  * `JSON.parse` keeps the last of two equal keys, so a second `"pre-tool"` further down a file would silently replace
  4 │  * the first and drop a guard. This reader refuses a duplicate key at any depth, bounds the nesting, and reports where
  5 │  * the problem is. The file open is the hardened one of the operator's `config.json` (config.ts), with the owner and
  6 │  * mode checks made optional for files whose trust comes from a content hash instead.
  7 │  */
  8 │ import * as fs from "node:fs";
  9 │ import { createHash } from "node:crypto";
 10 │ 
 11 │ /** Default nesting bound for records that are not hook files (matches the BG-1 reader). */
 12 │ export const STRICT_JSON_MAX_DEPTH = 32;
 13 │ 
 14 │ export class StrictJsonError extends Error {
 15 │   constructor(message: string, readonly line?: number, readonly column?: number) {
 16 │     super(line === undefined ? message : `line ${line}, column ${column}: ${message}`);
 17 │     this.name = "StrictJsonError";
 18 │   }
 19 │ }
 20 │ 
 21 │ /** Where each key of each parsed object was written, for messages about a key the caller rejects. */
 22 │ export type KeyPositions = WeakMap<object, Map<string, { line: number; column: number }>>;
 23 │ 
 24 │ export interface StrictJsonOptions {
 25 │   /** Deepest allowed nesting of objects and arrays (the root container is depth 1). Default `STRICT_JSON_MAX_DEPTH`. */
 26 │   maxDepth?: number;
 27 │   /** Filled with the position of every object key when given. */
 28 │   positions?: KeyPositions;
 29 │ }
 30 │ 
 31 │ const WHITESPACE = new Set([" ", "\t", "\n", "\r"]);
 32 │ const NUMBER = /-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?/y;
 33 │ 
 34 │ /** Parses one JSON value. Throws `StrictJsonError` on a syntax error, a duplicate key or nesting past `maxDepth`. */
 35 │ export function parseStrictJson(text: string, options: StrictJsonOptions | number = {}): unknown {
 36 │   const opts: StrictJsonOptions = typeof options === "number" ? { maxDepth: options } : options;
 37 │   const maxDepth = opts.maxDepth ?? STRICT_JSON_MAX_DEPTH;
 38 │   let at = 0;
 39 │ 
 40 │   const where = (offset: number) => {
