  1 │ /**
  2 │  * BG-3 trust and abuse model: rate limiting and quarantine for event triggers.
  3 │  *
  4 │  * Rate limits live on each trigger spec (trigger_spec.ts: `rate.maxPerMinute / maxPerHour / maxPerDay`) and are
  5 │  * enforced here per trigger (scope + id) and per workspace. A firer calls `checkAndRecord` before starting a trigger
  6 │  * run; when it returns denied the run never starts and the denial is recorded (receipt + flight log by the firer).
  7 │  *
  8 │  * Quarantine: a trigger that fails its own rate limit, crashes, or is denied by the gates N times in a row is
  9 │  * quarantined for a cooldown. While quarantined, every firing is denied immediately. This prevents a trigger that
 10 │  * keeps firing into a broken state from spinning (a webhook caller retrying on every failure, a file-change trigger
 11 │  * on a file the broken run keeps rewriting).
 12 │  *
 13 │  * All state is in-process (this process's trigger firer). Cross-process persistence of counters is the firer's job
 14 │  * (it writes the job/schedule store for BG-2 / the trigger store for BG-3); this module is the decision logic and the
 15 │  * tests below pin it.
 16 │  */
 17 │ 
 18 │ import type { TriggerRate } from "./trigger_spec.js";
 19 │ 
 20 │ /** A firing attempt and its outcome, recorded for the per-trigger history. */
 21 │ export interface TriggerAttempt {
 22 │   /** ISO 8601 of the attempt. */
 23 │   at: string;
 24 │   /** Whether the rate limit admitted it. */
 25 │   admitted: boolean;
 26 │   /** Why it was denied, when denied. */
 27 │   reason?: string;
 28 │ }
 29 │ 
 30 │ /** A quarantined trigger: no firing is admitted until `until` passes. */
 31 │ export interface TriggerQuarantine {
 32 │   /** ISO 8601 after which the trigger may fire again. */
 33 │   until: string;
 34 │   /** Why it was quarantined. */
 35 │   reason: string;
 36 │   /** Consecutive failures that led to this. */
 37 │   failures: number;
 38 │ }
 39 │ 
 40 │ export interface RateLimitDecision {
 41 │   admitted: boolean;
 42 │   /** Why denied, when `admitted` is false. */
 43 │   reason?: string;
 44 │   /** The per-trigger counter after this attempt (for the firer to persist). */
 45 │   triggerAttempts: TriggerAttempt[];
 46 │   /** Whether the trigger is now quarantined. */
 47 │   quarantined?: TriggerQuarantine;
 48 │ }
 49 │ 
 50 │ export const DEFAULT_QUARANTINE_FAILURES = 3;
 51 │ export const DEFAULT_QUARANTINE_COOLDOWN_MINUTES = 15;
 52 │ 
 53 │ /** A rate limiter for one trigger (one scope + id). Holds the sliding windows and the quarantine. */
 54 │ export class TriggerRateLimiter {
 55 │   private maxPerMinute: number;
 56 │   private maxPerHour: number;
 57 │   private maxPerDay: number;
 58 │   private readonly maxFailures: number;
 59 │   private readonly cooldownMinutes: number;
 60 │   private attempts: TriggerAttempt[] = [];
 61 │   private quarantined: TriggerQuarantine | undefined;
 62 │   private consecutiveFailures = 0;
 63 │ 
 64 │   constructor(rate: TriggerRate, options?: { maxFailures?: number; cooldownMinutes?: number }) {
 65 │     this.maxPerMinute = rate.maxPerMinute;
 66 │     this.maxPerHour = rate.maxPerHour;
 67 │     this.maxPerDay = rate.maxPerDay;
 68 │     this.maxFailures = options?.maxFailures ?? DEFAULT_QUARANTINE_FAILURES;
 69 │     this.cooldownMinutes = options?.cooldownMinutes ?? DEFAULT_QUARANTINE_COOLDOWN_MINUTES;
 70 │   }
 71 │ 
 72 │   /** Call before starting a trigger run. Returns whether it is admitted and updates internal state. */
 73 │   public checkAndRecord(now: Date): RateLimitDecision {
 74 │     const at = now.toISOString();
 75 │ 
 76 │     // Quarantine wins: while quarantined, nothing is admitted.
 77 │     if (this.quarantined) {
 78 │       if (now < new Date(this.quarantined.until)) {
 79 │         this.record(at, false, "quarantined");
 80 │         return { admitted: false, reason: "quarantined", triggerAttempts: [...this.attempts], quarantined: this.quarantined };
 81 │       }
 82 │       // Cooldown passed: release, reset the failure count.
 83 │       this.quarantined = undefined;
 84 │       this.consecutiveFailures = 0;
 85 │     }
 86 │ 
 87 │     const admitted = this.withinLimits(now);
 88 │     this.record(at, admitted, admitted ? undefined : "rate limit");
 89 │ 
 90 │     if (admitted) {
 91 │       this.consecutiveFailures = 0;
 92 │     } else {
 93 │       this.consecutiveFailures++;
 94 │       if (this.consecutiveFailures >= this.maxFailures && !this.quarantined) {
 95 │         const until = new Date(now.getTime() + this.cooldownMinutes * 60 * 1000).toISOString();
 96 │         this.quarantined = { until, reason: `rate limit exceeded ${this.maxFailures} times in a row`, failures: this.consecutiveFailures };
 97 │         return { admitted: false, reason: "quarantined", triggerAttempts: [...this.attempts], quarantined: this.quarantined };
 98 │       }
 99 │     }
100 │ 
101 │     return { admitted, reason: admitted ? undefined : "rate limit", triggerAttempts: [...this.attempts] };
102 │   }
103 │ 
104 │   /** Record an externally-reported failure (the run was denied by the gates, crashed, or produced no progress) so it
105 │    * counts toward quarantine. The firer calls this when a run ends without completing. */
106 │   public recordFailure(now: Date, reason: string): RateLimitDecision {
107 │     const at = now.toISOString();
108 │     this.record(at, false, reason);
109 │     this.consecutiveFailures++;
110 │     if (this.consecutiveFailures >= this.maxFailures && !this.quarantined) {
111 │       const until = new Date(now.getTime() + this.cooldownMinutes * 60 * 1000).toISOString();
112 │       this.quarantined = { until, reason: `${reason} (${this.maxFailures} times in a row)`, failures: this.consecutiveFailures };
113 │       return { admitted: false, reason: "quarantined", triggerAttempts: [...this.attempts], quarantined: this.quarantined };
114 │     }
115 │     return { admitted: false, reason, triggerAttempts: [...this.attempts] };
116 │   }
117 │ 
118 │   /** Release a quarantine early (operator action: `nexus triggers release`). */
119 │   public releaseQuarantine(): void {
120 │     this.quarantined = undefined;
121 │     this.consecutiveFailures = 0;
122 │   }
123 │ 
124 │   /** Snapshot for persistence / tests. The per-trigger rate is persisted so a restored limiter enforces the
125 │    * configured limits again instead of falling back to a default. */
126 │   public snapshot(): { rate: TriggerRate; attempts: TriggerAttempt[]; quarantined?: TriggerQuarantine; consecutiveFailures: number } {
127 │     return {
128 │       rate: { maxPerMinute: this.maxPerMinute, maxPerHour: this.maxPerHour, maxPerDay: this.maxPerDay },
129 │       attempts: [...this.attempts],
130 │       quarantined: this.quarantined,
131 │       consecutiveFailures: this.consecutiveFailures,
132 │     };
133 │   }
134 │ 
135 │   /** Restore from a snapshot (the firer reloads persisted state here). Re-applies the persisted rate when present. */
136 │   public restore(snapshot: { rate?: TriggerRate; attempts?: TriggerAttempt[]; quarantined?: TriggerQuarantine; consecutiveFailures?: number }): void {
137 │     if (snapshot.rate) {
138 │       this.maxPerMinute = snapshot.rate.maxPerMinute;
139 │       this.maxPerHour = snapshot.rate.maxPerHour;
140 │       this.maxPerDay = snapshot.rate.maxPerDay;
141 │     }
142 │     this.attempts = snapshot.attempts ?? [];
143 │     this.quarantined = snapshot.quarantined;
144 │     this.consecutiveFailures = snapshot.consecutiveFailures ?? 0;
145 │   }
146 │ 
147 │   private record(at: string, admitted: boolean, reason?: string): void {
148 │     this.attempts.push({ at, admitted, ...(reason ? { reason } : {}) });
149 │     this.prune(nowForPrune(at));
150 │   }
151 │ 
152 │   private withinLimits(now: Date): boolean {
153 │     const minuteAgo = new Date(now.getTime() - 60 * 1000);
154 │     const hourAgo = new Date(now.getTime() - 60 * 60 * 1000);
155 │     const dayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);
156 │ 
157 │     let perMinute = 0;
158 │     let perHour = 0;
159 │     let perDay = 0;
160 │     for (const a of this.attempts) {
161 │       const t = new Date(a.at);
162 │       if (t >= dayAgo) {
163 │         perDay++;
164 │         if (t >= hourAgo) {
165 │           perHour++;
166 │           if (t >= minuteAgo) perMinute++;
167 │         }
168 │       }
169 │     }
170 │     return perMinute < this.maxPerMinute && perHour < this.maxPerHour && perDay < this.maxPerDay;
171 │   }
172 │ 
173 │   private prune(now: Date): void {
174 │     const dayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);
175 │     this.attempts = this.attempts.filter((a) => new Date(a.at) >= dayAgo);
176 │   }
177 │ }
178 │ 
179 │ function nowForPrune(at: string): Date {
180 │   const d = new Date(at);
181 │   return Number.isNaN(d.getTime()) ? new Date() : d;
182 │ }
183 │ 
184 │ /** A workspace-wide rate limiter: one `TriggerRateLimiter` per trigger id, plus a workspace-level counter. */
185 │ export class WorkspaceRateLimiter {
186 │   private readonly limiters = new Map<string, TriggerRateLimiter>();
187 │   private workspaceAttempts: TriggerAttempt[] = [];
188 │   private readonly workspaceMaxPerMinute: number;
189 │   private readonly workspaceMaxPerHour: number;
190 │   private readonly workspaceMaxPerDay: number;
191 │ 
192 │   constructor(workspaceLimits: { maxPerMinute: number; maxPerHour: number; maxPerDay: number }) {
193 │     this.workspaceMaxPerMinute = workspaceLimits.maxPerMinute;
194 │     this.workspaceMaxPerHour = workspaceLimits.maxPerHour;
195 │     this.workspaceMaxPerDay = workspaceLimits.maxPerDay;
196 │   }
197 │ 
198 │   /** Get or create the limiter for `triggerId`. */
199 │   public limiterFor(triggerId: string, rate: TriggerRate): TriggerRateLimiter {
200 │     let limiter = this.limiters.get(triggerId);
201 │     if (!limiter) {
202 │       limiter = new TriggerRateLimiter(rate);
203 │       this.limiters.set(triggerId, limiter);
204 │     }
205 │     return limiter;
206 │   }
207 │ 
208 │   /** Record a workspace-level firing attempt (any trigger). Returns whether the workspace is still within its limits. */
209 │   public recordWorkspaceAttempt(now: Date, admitted: boolean, reason?: string): void {
210 │     const at = now.toISOString();
211 │     this.workspaceAttempts.push({ at, admitted, ...(reason ? { reason } : {}) });
212 │     this.pruneWorkspace(now);
213 │   }
214 │ 
215 │   /** Whether the workspace is within its own rate limits right now (independent of any single trigger). */
216 │   public workspaceWithinLimits(now: Date): boolean {
217 │     const minuteAgo = new Date(now.getTime() - 60 * 1000);
218 │     const hourAgo = new Date(now.getTime() - 60 * 60 * 1000);
219 │     const dayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);
220 │     let perMinute = 0;
221 │     let perHour = 0;
222 │     let perDay = 0;
223 │     for (const a of this.workspaceAttempts) {
224 │       const t = new Date(a.at);
225 │       if (t >= dayAgo) {
226 │         perDay++;
227 │         if (t >= hourAgo) {
228 │           perHour++;
229 │           if (t >= minuteAgo) perMinute++;
230 │         }
231 │       }
232 │     }
233 │     return perMinute < this.workspaceMaxPerMinute && perHour < this.workspaceMaxPerHour && perDay < this.workspaceMaxPerDay;
234 │   }
235 │ 
236 │   public snapshot(): { perTrigger: Array<[string, ReturnType<TriggerRateLimiter["snapshot"]>]>; workspaceAttempts: TriggerAttempt[] } {
237 │     return {
238 │       perTrigger: [...this.limiters.entries()].map(([id, limiter]) => [id, limiter.snapshot()]),
239 │       workspaceAttempts: [...this.workspaceAttempts],
240 │     };
241 │   }
242 │ 
243 │   public restore(snapshot: { perTrigger?: Array<[string, ReturnType<TriggerRateLimiter["snapshot"]>]>; workspaceAttempts?: TriggerAttempt[] }): void {
244 │     this.limiters.clear();
245 │     for (const [id, s] of snapshot.perTrigger ?? []) {
246 │       const limiter = new TriggerRateLimiter(s.rate ?? { maxPerMinute: 1, maxPerHour: 1, maxPerDay: 1 });
247 │       limiter.restore(s);
248 │       this.limiters.set(id, limiter);
249 │     }
250 │     this.workspaceAttempts = snapshot.workspaceAttempts ?? [];
251 │   }
252 │ 
253 │   private pruneWorkspace(now: Date): void {
254 │     const dayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);
255 │     this.workspaceAttempts = this.workspaceAttempts.filter((a) => new Date(a.at) >= dayAgo);
256 │   }
257 │ }
258 │ 
259 │ /** Default workspace-level caps: a workspace cannot flood the runner regardless of how many triggers it has. */
260 │ export const DEFAULT_WORKSPACE_LIMITS = { maxPerMinute: 30, maxPerHour: 300, maxPerDay: 2000 };

